#!/usr/bin/env node
// Portable Phase E verifier. Evidence is generated by real child processes only.
import { spawn } from 'node:child_process';
import { mkdir, writeFile, readFile, stat } from 'node:fs/promises';
import { basename, join, resolve } from 'node:path';

const repo = process.env.PHASE_E_REPO || basename(process.cwd());
const target = process.env.PHASE_E_URL || 'http://127.0.0.1:4173/';
const url = new URL(target);
if (!['http:', 'https:'].includes(url.protocol) || !/^[A-Za-z0-9_.-]+$/.test(repo)) throw Error('Invalid target');
const output = resolve('.audit', repo, 'tools'), started = new Date().toISOString();
await mkdir(output, { recursive: true });
const records = [], failures = [];
const json = async (name, value) => writeFile(join(output, name), JSON.stringify(value, null, 2) + '\n');
function run(name, program, args, timeoutMs=120000) {
  return new Promise(resolveResult => {
    const command = [program, ...args].map(x => /\s/.test(x) ? JSON.stringify(x) : x).join(' ');
    const child = spawn(program, args, {env:{...process.env, NO_COLOR:'1'},stdio:['ignore','pipe','pipe']});
    let stdout='', stderr='', complete=false;
    const finish = async (code, error) => {
      if (complete) return; complete=true; clearTimeout(timeout);
      const result={name, repo, target, at:new Date().toISOString(), command, exitCode:code, error, stdout:stdout.slice(0,500000), stderr:stderr.slice(0,500000)};
      await json(name+'-attempt.json',result);
      await writeFile(join(output,name+'.stdout.log'),stdout);
      await writeFile(join(output,name+'.stderr.log'),stderr);
      resolveResult(result);
    };
    child.stdout.on('data',x=>stdout+=x);child.stderr.on('data',x=>stderr+=x);
    child.on('error', e=>finish(null,String(e)));
    child.on('close', (code,signal)=>finish(code,code===0?'':(stderr||signal||'nonzero exit').slice(0,2000)));
    const timeout=setTimeout(()=>{child.kill('SIGTERM');finish(null,'TIMEOUT '+timeoutMs+'ms')},timeoutMs);
  });
}
async function check(name, program, args, timeout, expectation) {
  const r=await run(name, program,args,timeout);
  let passing=r.exitCode===0;
  if (passing && expectation==='json') {
    try {
      const data=JSON.parse(r.stdout);
      await json(name+'.json',{repo,target,at:r.at,command:r.command,data});
    } catch(e) {passing=false;r.error='Invalid JSON output: '+e;}
  }
  if (passing && expectation?.startsWith('file:')) {
    const file=expectation.slice(5);
    try{passing=(await stat(file)).size>0;}catch{passing=false;}
    if(!passing)r.error='Required output missing or empty: '+file;
  }
  records.push({name,at:r.at,command:r.command,status:passing?'passed':'failed',error:r.error||''});
  if(!passing)failures.push(records.at(-1));
}
// Perform real CLI tests against this repository's development server.
await json('pa11y-config.json',{defaults:{standard:'WCAG2AA',timeout:30000},urls:[target]});
const lhci={ci:{collect:{url:[target],numberOfRuns:3},assert:{preset:'lighthouse:recommended',assertions:{
  'categories:performance':['error',{minScore:0.9}],
  'categories:accessibility':['error',{minScore:1}],
  'categories:best-practices':['error',{minScore:0.95}],
  'categories:seo':['error',{minScore:0.95}]
}}}};
await json('lighthouserc.json',lhci);
// Unverified command provenance: inspect npm registry without running arbitrary code.
for(const mode of ['scan','bundle','static']){
  const name='frontend-qa-'+mode;
  const r=await run(name+'-registry','npm',['view','frontend-qa','name','version','repository','--json'],30000);
  const blocked={name,at:r.at,command:r.command,status:'blocked',error:r.error||'No verified package provenance or CLI contract. npm metadata inspected; executable not invoked.'};
  records.push(blocked);failures.push(blocked);
}
await check('lighthouse-ci','npx',['--yes','@lhci/cli@latest','autorun','--config',join(output,'lighthouserc.json')],240000);
await check('pa11y','npx',['--yes','pa11y-ci','--json','--config',join(output,'pa11y-config.json')],120000,'json');
await check('html-validate','npx',['--yes','html-validate','--formatter','json','client/**/*.html','campus/**/*.html'],120000,'json');
await check('axe-cli','npx',['--yes','@axe-core/cli',target,'--tags','wcag2a,wcag2aa,wcag21a,wcag21aa,wcag22aa','--save',join(output,'axe-cli-output.json')],120000,'file:'+join(output,'axe-cli-output.json'));
// Evidence: actual desktop/tablet/mobile screenshots, not placeholder PNG files.
for(const [device,viewport] of [['desktop','1440,900'],['tablet','820,1180'],['mobile','390,844']]){
  const file=join(output,'playwright-'+device+'.png');
  await check('screenshot-'+device,'npx',['--yes','playwright','screenshot','--browser','chromium','--viewport-size',viewport,'--full-page',target,file],120000,'file:'+file);
}
await check('webperf','docker',['run','--rm','--network','host','webperf/core:latest','--url',target],120000);

// Each MCP must prove an actual tool-call, not just a registry entry.
// Until verified client execution is available, a registry probe is NOT a pass.
const mcp={
 'chrome-devtools':'chrome-devtools-mcp@latest',
 playwright:'@playwright/mcp@latest',
 'axe-devtools':'axe-devtools-mcp',
 cdp:'cdp-mcp',
 'web-validator':'mcp-web-validator',
 w3c:'@shuji-bonji/w3c-mcp',
 uimax:'uimax-mcp',
 'frontend-inspo':'frontend-inspo-mcp',
};
// A real MCP tool call, including the response, is necessary for a PASS.
async function callMCP(name, pkg, preferred, inputs) {
  return new Promise(resolveResult => {
    const command='npx --yes '+pkg+' [stdio initialize -> tools/list -> tools/call]';
    const child=spawn('npx',['--yes',pkg],{stdio:['pipe','pipe','pipe'],env:{...process.env,CI:'true',NO_COLOR:'1'}});
    let buffer='', stderr='', stage='initialize', completed=false, tool=null, raw=[];
    const send=(id,method,params)=>child.stdin.write(JSON.stringify({jsonrpc:'2.0',id,method,params})+'\n');
    const finish=async(ok,error)=>{
      if(completed)return; completed=true;clearTimeout(timer);child.kill('SIGTERM');
      const result={name,at:new Date().toISOString(),command,repo,target,tool:tool?.name||null,status:ok?'passed':'failed',error:error||'',responses:raw.slice(0,12),stderr:stderr.slice(0,5000)};
      await json(name+'-mcp.json',result);
      records.push(result);
      if(!ok)failures.push(result);
      resolveResult(result);
    };
    child.on('error',e=>finish(false,String(e)));
    child.on('close',(code,signal)=>finish(false,'MCP process exited before tools/call response. exit='+code+' signal='+signal+' stderr='+stderr.slice(-1000)));
    child.stderr.on('data',d=>{stderr+=d.toString()});
    child.stdout.on('data',d=>{
      buffer+=d.toString();
      let index;
      while((index=buffer.indexOf('\n'))>=0){
        const line=buffer.slice(0,index);buffer=buffer.slice(index+1);
        let msg;try{msg=JSON.parse(line)}catch{continue}
        raw.push(msg);
        if(msg.id===1){
          if(msg.error){finish(false,JSON.stringify(msg.error));return}
          child.stdin.write(JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'})+'\n');
          send(2,'tools/list',{});stage='list';
        }else if(msg.id===2){
          if(msg.error){finish(false,JSON.stringify(msg.error));return}
          const available=msg.result?.tools||[];
          tool=available.find(t=>t.name===preferred);
          if(!tool){finish(false,'Expected tool unavailable: '+preferred+'; tools: '+available.map(t=>t.name).join(','));return}
          const required=tool.inputSchema?.required||[];
          if(required.some(k=>!(k in inputs))){finish(false,'Missing required arguments: '+JSON.stringify(required));return}
          send(3,'tools/call',{name:tool.name,arguments:inputs});stage='call';
        }else if(msg.id===3){
          finish(!msg.error && !msg.result?.isError,msg.error?JSON.stringify(msg.error):msg.result?.isError?JSON.stringify(msg.result):'');
          return;
        }
      }
    });
    send(1,'initialize',{protocolVersion:'2025-03-26',capabilities:{},clientInfo:{name:'belentani-phase-e',version:'1.0.0'}});
    const timer=setTimeout(()=>finish(false,'MCP '+stage+' timed out after 45000ms'),45000);
  });
}
for(const [name,pkg] of Object.entries(mcp)){
  if(name==='playwright') await callMCP(name,pkg,'browser_navigate',{url:target});
  else if(name==='chrome-devtools') await callMCP(name,pkg,'navigate_page',{type:'url',url:target});
  else if(name==='w3c') await callMCP(name,pkg,'search_w3c_specs',{query:'HTML accessibility semantic landmarks'});
  else{
    const r=await run(name+'-registry','npm',['view',pkg,'name','version','repository','--json'],30000);
    const evidence={name,at:r.at,command:r.command,status:'blocked',error:r.error||'Package metadata checked; MCP server execution blocked pending independent package provenance and tool contract validation.'};
    records.push(evidence);failures.push(evidence);
  }
}
const external={name:'midos',at:new Date().toISOString(),command:'MCP initialize + tools/call https://midos.dev/mcp',status:'blocked',error:'External MCP session not authenticated or invoked from an MCP client.'};
records.push(external);failures.push(external);
for(const [name,pkg] of Object.entries({
 foxhole:'@ku5ic/foxhole',webby:'@stacktown/webby','web-quality':'web-quality-mcp',
 sytecheck:'@ascentws/sytecheck-mcp',accesslumens:'@accesslumens/mcp',
 'lo-eyes':'lo-eyes','a11y-copilot':'@catiarodrigues/a11y-copilot'
})){
  const r=await run(name+'-registry','npm',['view',pkg,'name','version','repository','--json'],30000);
  const evidence={name,at:r.at,command:r.command,status:'blocked',error:r.error||'Only metadata checked. Unverified npm executables intentionally not launched.'};
  records.push(evidence);failures.push(evidence);
}
const summary={repo,target,started,finished:new Date().toISOString(),status:failures.length?'BLOCKED':'PASS',passed:records.length-failures.length,total:records.length,records};
await json('manifest.json',summary);
await writeFile(join(output,'SKIPPED.md'),'# Failed or blocked tools\n\n'+failures.map(x=>
  '## '+x.name+'\n- Timestamp: '+x.at+'\n- Command: `'+x.command+'`\n- Error literal: ```\n'+x.error+'\n```\n'
).join('\n'));
await json('GATE.json',{repo,target,at:summary.finished,gate:summary.status,failed:failures.length});
console.log(JSON.stringify({status:summary.status,passed:summary.passed,total:summary.total}));
if(failures.length) process.exitCode=1;
